function normalizedTransactionType(value){
  return value==='Travel Expense' ? 'Travel Expenses' : value;
}

function normalizedTransactionStatus(value){
  return value==='Done'?'Done':'Draft';
}

function normalizedTemplateCompletion(transaction={}){
  const existing=transaction.templateCompletion||{};
  const fallback=normalizedTransactionStatus(transaction.status)==='Done'?'complete':'incomplete';
  return TEMPLATE_KEYS.reduce((completion,key)=>{
    completion[key]=existing[key]==='complete'?'complete':existing[key]==='incomplete'?'incomplete':fallback;
    return completion;
  },{});
}

function statusFromTemplateCompletion(completion){
  return TEMPLATE_KEYS.every(key=>completion[key]==='complete')?'Done':'Draft';
}

function loadTransactionFields(t){
  fieldIds.forEach(k=>{
    const value=k==='type' ? normalizedTransactionType(t[k]) : (t[k]||'');
    document.getElementById(k).value=value;
  });
}

function applyTransactionType(){
  const type=document.getElementById('type').value;
  const config=transactionTypes[type];
  if(!config)return;
  document.getElementById('ffp').value=config.ffp;
  document.getElementById('accountCode').value=config.accountCode;
  document.getElementById('particulars').value=config.particulars;
  document.getElementById('formTitle').textContent=`${editingId?'Edit':'New'} ${type} Transaction`;
}

