function showApiStatus(message,tone='info',autoHideMs=0){
  const status=document.getElementById('apiStatus');
  if(!status)return;
  clearTimeout(apiStatusTimer);
  status.textContent=message;
  status.className=`api-status no-print show ${tone}`;
  if(autoHideMs)apiStatusTimer=setTimeout(()=>status.classList.remove('show'),autoHideMs);
}

function apiUrl(path=''){
  const base=String(API_CONFIG.apiBaseUrl||'').replace(/\/$/,'');
  if(!base)throw new Error('The API URL is not configured in config.js.');
  return `${base}${path}`;
}

async function apiRequest(path,options={}){
  const controller=new AbortController();
  const timeout=setTimeout(()=>controller.abort(),Number(API_CONFIG.requestTimeoutMs)||20000);
  try{
    const response=await fetch(apiUrl(path),{
      method:options.method||'GET',
      credentials:'include',
      headers:{'Accept':'application/json',...(options.body?{'Content-Type':'application/json'}:{}),...(options.headers||{})},
      body:options.body?JSON.stringify(options.body):undefined,
      signal:controller.signal
    });
    const payload=await response.json().catch(()=>null);
    if(!response.ok||!payload?.ok)throw new Error(payload?.error||`API request failed (${response.status}).`);
    return payload.data;
  }catch(error){
    if(error.name==='AbortError')throw new Error('The database request timed out. Please check the connection and try again.');
    throw error;
  }finally{
    clearTimeout(timeout);
  }
}

async function fetchTransaction(id){
  const transaction=await apiRequest(`/transactions/${encodeURIComponent(id)}`);
  const index=transactions.findIndex(item=>item.id===transaction.id);
  if(index>=0)transactions[index]=transaction;else transactions.unshift(transaction);
  return transaction;
}

async function loadRemoteState(){
  showApiStatus('Connecting to the transaction database…','info');
  const [remoteTransactions,remoteSettings]=await Promise.all([
    apiRequest('/transactions'),
    apiRequest('/settings')
  ]);
  transactions=Array.isArray(remoteTransactions)?remoteTransactions:[];
  systemSettings=remoteSettings||defaultSettings;
  remoteReady=true;
  showApiStatus('Google Sheets database connected.','success',2200);
}
