function money(n){return Number(n||0).toLocaleString('en-PH',{minimumFractionDigits:2,maximumFractionDigits:2})}
function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]))}
function fdate(v){if(!v)return '';return new Date(v+'T00:00:00').toLocaleDateString('en-US',{month:'long',day:'numeric',year:'numeric'})}
function sdate(v){if(!v)return '';return new Date(v+'T00:00:00').toLocaleDateString('en-US',{month:'2-digit',day:'2-digit',year:'numeric'})}
function time12(v){
  if(!v)return '';
  const [h,m]=v.split(':').map(Number);
  const suffix=h>=12?'PM':'AM';
  const hour=(h%12)||12;
  return `${hour}:${String(m).padStart(2,'0')} ${suffix}`;
}
function normalizeDateRange(v){
  v=String(v||'').trim().replace(/\s+/g,'');
  if(!v)return '';
  const single=v.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
  const range=v.match(/^(\d{1,2})\/(\d{1,2})-(\d{1,2})\/(\d{4})$/);
  if(single){
    const month=Number(single[1]), day=Number(single[2]), year=Number(single[3]);
    if(month>=1&&month<=12&&day>=1&&day<=31)
      return `${String(month).padStart(2,'0')}/${day}/${year}`;
  }
  if(range){
    const month=Number(range[1]), first=Number(range[2]), last=Number(range[3]), year=Number(range[4]);
    if(month>=1&&month<=12&&first>=1&&first<=31&&last>=first&&last<=31)
      return `${String(month).padStart(2,'0')}/${first}-${last}/${year}`;
  }
  return v;
}
function validDateRange(v){
  if(!String(v||'').trim()) return true;
  const n=normalizeDateRange(v);
  const m=n.match(/^(\d{2})\/(\d{1,2})(?:-(\d{1,2}))?\/(\d{4})$/);
  if(!m) return false;
  const month=Number(m[1]), first=Number(m[2]), last=m[3]?Number(m[3]):first;
  return month>=1&&month<=12&&first>=1&&first<=31&&last>=first&&last<=31;
}
function normalizeItineraryRows(rows){
  return (rows||[]).map(r=>{
    let dateRangeValue=r.dateRange||'';
    if(!dateRangeValue && (r.dateFrom||r.date)){
      const firstDate=new Date((r.dateFrom||r.date)+'T00:00:00');
      if(r.dateTo && r.dateTo!==r.dateFrom){
        const lastDate=new Date(r.dateTo+'T00:00:00');
        if(firstDate.getMonth()===lastDate.getMonth() && firstDate.getFullYear()===lastDate.getFullYear()){
          dateRangeValue=`${String(firstDate.getMonth()+1).padStart(2,'0')}/${firstDate.getDate()}-${lastDate.getDate()}/${firstDate.getFullYear()}`;
        } else {
          dateRangeValue=`${String(firstDate.getMonth()+1).padStart(2,'0')}/${firstDate.getDate()}/${firstDate.getFullYear()}`;
        }
      } else {
        dateRangeValue=`${String(firstDate.getMonth()+1).padStart(2,'0')}/${firstDate.getDate()}/${firstDate.getFullYear()}`;
      }
    }
    return {
      ...r,
      dateRange:dateRangeValue,
      departure:/^\d{1,2}:\d{2}$/.test(r.departure||'') ? r.departure : '',
      arrival:/^\d{1,2}:\d{2}$/.test(r.arrival||'') ? r.arrival : ''
    };
  });
}

