function travelDateRange(t){
  const from=fdate(t.travelFrom),to=fdate(t.dateReturn||t.travelTo);
  if(from&&to)return from===to?from:`${from} – ${to}`;
  return from||to||'—';
}
function travelFromToRange(t){
  const fromValue=t.travelFrom,toValue=t.travelTo;
  if(!fromValue||!toValue)return fdate(fromValue||toValue)||'—';
  const from=new Date(fromValue+'T00:00:00'),to=new Date(toValue+'T00:00:00');
  if(from.getFullYear()===to.getFullYear()&&from.getMonth()===to.getMonth()){
    const month=from.toLocaleDateString('en-US',{month:'long'});
    const days=from.getDate()===to.getDate()?`${from.getDate()}`:`${from.getDate()}-${to.getDate()}`;
    return `${month} ${days}, ${from.getFullYear()}`;
  }
  return `${fdate(fromValue)} – ${fdate(toValue)}`;
}

function xmlEsc(value=''){
  return String(value)
    .replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/g,'')
    .replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]));
}
function excelColumn(index){
  let result='';
  while(index>0){index--;result=String.fromCharCode(65+(index%26))+result;index=Math.floor(index/26)}
  return result;
}
function xlsxCell(reference,item){
  const cell=item&&typeof item==='object'&&!Array.isArray(item)?item:{value:item};
  const style=cell.style?` s="${cell.style}"`:'';
  if(cell.formula){
    return `<c r="${reference}"${style}><f>${xmlEsc(cell.formula)}</f><v>${Number(cell.value||0)}</v></c>`;
  }
  if(cell.numeric){
    return `<c r="${reference}"${style}><v>${Number(cell.value||0)}</v></c>`;
  }
  return `<c r="${reference}" t="inlineStr"${style}><is><t xml:space="preserve">${xmlEsc(cell.value??'')}</t></is></c>`;
}
function formCell(value='',style=5,options={}){return {value,style,...options}}
function createFormSheet(columnWidths,orientation='portrait'){
  const rows=[],merges=[];
  let rowNumber=0;
  const addRow=(cells=[],height=18)=>{
    rowNumber++;
    const content=cells.map((item,index)=>item===null||item===undefined?'':xlsxCell(`${excelColumn(index+1)}${rowNumber}`,item)).join('');
    rows.push(`<row r="${rowNumber}" ht="${height}" customHeight="1">${content}</row>`);
    return rowNumber;
  };
  const addSegments=(segments,height=18)=>{
    const cells=Array(columnWidths.length).fill(null);
    segments.forEach(segment=>{
      const style=segment.style??5;
      for(let column=segment.from;column<=segment.to;column++) cells[column-1]=formCell('',style);
      cells[segment.from-1]=formCell(segment.value??'',style,{numeric:segment.numeric,formula:segment.formula});
      if(segment.to>segment.from)merges.push(`${excelColumn(segment.from)}${rowNumber+1}:${excelColumn(segment.to)}${rowNumber+1}`);
    });
    return addRow(cells,height);
  };
  const merge=range=>merges.push(range);
  const toXml=()=>`<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">
  <sheetPr><pageSetUpPr fitToPage="1"/></sheetPr>
  <sheetViews><sheetView showGridLines="0" workbookViewId="0"/></sheetViews>
  <cols>${columnWidths.map((width,index)=>`<col min="${index+1}" max="${index+1}" width="${width}" customWidth="1"/>`).join('')}</cols>
  <sheetData>${rows.join('')}</sheetData>
  ${merges.length?`<mergeCells count="${merges.length}">${merges.map(range=>`<mergeCell ref="${range}"/>`).join('')}</mergeCells>`:''}
  <printOptions horizontalCentered="1"/>
  <pageMargins left="0.25" right="0.25" top="0.35" bottom="0.35" header="0.15" footer="0.15"/>
  <pageSetup paperSize="9" orientation="${orientation}" fitToWidth="1" fitToHeight="1"/>
</worksheet>`;
  return {addRow,addSegments,merge,toXml,get rowNumber(){return rowNumber}};
}
