function crc32(bytes){
  let crc=0xFFFFFFFF;
  for(const byte of bytes){
    crc^=byte;
    for(let i=0;i<8;i++) crc=(crc>>>1)^((crc&1)?0xEDB88320:0);
  }
  return (crc^0xFFFFFFFF)>>>0;
}
function joinBytes(parts){
  const size=parts.reduce((sum,part)=>sum+part.length,0),result=new Uint8Array(size);
  let offset=0;
  parts.forEach(part=>{result.set(part,offset);offset+=part.length});
  return result;
}
function createXlsxZip(files){
  const encoder=new TextEncoder(),localParts=[],centralParts=[];
  const now=new Date(),year=Math.max(1980,now.getFullYear());
  const dosTime=(now.getHours()<<11)|(now.getMinutes()<<5)|(now.getSeconds()>>1);
  const dosDate=((year-1980)<<9)|((now.getMonth()+1)<<5)|now.getDate();
  let localOffset=0,centralSize=0;

  Object.entries(files).forEach(([name,content])=>{
    const nameBytes=encoder.encode(name),data=encoder.encode(content),checksum=crc32(data);
    const local=new Uint8Array(30+nameBytes.length),lv=new DataView(local.buffer);
    lv.setUint32(0,0x04034B50,true);lv.setUint16(4,20,true);lv.setUint16(6,0,true);lv.setUint16(8,0,true);
    lv.setUint16(10,dosTime,true);lv.setUint16(12,dosDate,true);lv.setUint32(14,checksum,true);
    lv.setUint32(18,data.length,true);lv.setUint32(22,data.length,true);lv.setUint16(26,nameBytes.length,true);lv.setUint16(28,0,true);
    local.set(nameBytes,30);
    localParts.push(local,data);

    const central=new Uint8Array(46+nameBytes.length),cv=new DataView(central.buffer);
    cv.setUint32(0,0x02014B50,true);cv.setUint16(4,20,true);cv.setUint16(6,20,true);cv.setUint16(8,0,true);cv.setUint16(10,0,true);
    cv.setUint16(12,dosTime,true);cv.setUint16(14,dosDate,true);cv.setUint32(16,checksum,true);
    cv.setUint32(20,data.length,true);cv.setUint32(24,data.length,true);cv.setUint16(28,nameBytes.length,true);
    cv.setUint16(30,0,true);cv.setUint16(32,0,true);cv.setUint16(34,0,true);cv.setUint16(36,0,true);cv.setUint32(38,0,true);
    cv.setUint32(42,localOffset,true);central.set(nameBytes,46);
    centralParts.push(central);centralSize+=central.length;localOffset+=local.length+data.length;
  });

  const end=new Uint8Array(22),ev=new DataView(end.buffer),fileCount=Object.keys(files).length;
  ev.setUint32(0,0x06054B50,true);ev.setUint16(4,0,true);ev.setUint16(6,0,true);
  ev.setUint16(8,fileCount,true);ev.setUint16(10,fileCount,true);ev.setUint32(12,centralSize,true);
  ev.setUint32(16,localOffset,true);ev.setUint16(20,0,true);
  return joinBytes([...localParts,...centralParts,end]);
}
