const calendarState={
  rowIndex:null,
  fieldId:null,
  mode:'range',
  year:new Date().getFullYear(),
  month:new Date().getMonth(),
  start:null,
  end:null
};

function parseCompactRange(v){
  const n=normalizeDateRange(v);
  let m=n.match(/^(\d{2})\/(\d{1,2})-(\d{1,2})\/(\d{4})$/);
  if(m) return {month:Number(m[1])-1,start:Number(m[2]),end:Number(m[3]),year:Number(m[4])};
  m=n.match(/^(\d{2})\/(\d{1,2})\/(\d{4})$/);
  if(m) return {month:Number(m[1])-1,start:Number(m[2]),end:Number(m[2]),year:Number(m[3])};
  return null;
}

function compactRange(year,month,start,end){
  if(!start) return '';
  const mm=String(month+1).padStart(2,'0');
  const last=end||start;
  return start===last ? `${mm}/${start}/${year}` : `${mm}/${start}-${last}/${year}`;
}

function openCalendarPicker(rowIndex){
  calendarState.rowIndex=rowIndex;
  calendarState.fieldId=null;
  calendarState.mode='range';
  const parsed=parseCompactRange(itinerary[rowIndex]?.dateRange||'');
  const now=new Date();
  if(parsed){
    calendarState.year=parsed.year;
    calendarState.month=parsed.month;
    calendarState.start=parsed.start;
    calendarState.end=parsed.end;
  }else{
    calendarState.year=now.getFullYear();
    calendarState.month=now.getMonth();
    calendarState.start=null;
    calendarState.end=null;
  }
  document.getElementById('calendarModal').classList.add('open');
  document.getElementById('calendarModal').setAttribute('aria-hidden','false');
  renderCalendarPicker();
}

function openTravelDatePicker(fieldId){
  calendarState.rowIndex=null;
  calendarState.fieldId=fieldId;
  calendarState.mode='single';
  const value=document.getElementById(fieldId).value;
  const parsed=value.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  const now=new Date();
  if(parsed){
    calendarState.year=Number(parsed[1]);
    calendarState.month=Number(parsed[2])-1;
    calendarState.start=Number(parsed[3]);
    calendarState.end=Number(parsed[3]);
  }else{
    calendarState.year=now.getFullYear();
    calendarState.month=now.getMonth();
    calendarState.start=null;
    calendarState.end=null;
  }
  document.getElementById('calendarModal').classList.add('open');
  document.getElementById('calendarModal').setAttribute('aria-hidden','false');
  renderCalendarPicker();
}

function closeCalendarPicker(){
  document.getElementById('calendarModal').classList.remove('open');
  document.getElementById('calendarModal').setAttribute('aria-hidden','true');
}

function renderCalendarPicker(){
  const y=calendarState.year,m=calendarState.month;
  const monthName=new Date(y,m,1).toLocaleDateString('en-US',{month:'long',year:'numeric'});
  document.getElementById('calendarTitle').textContent=monthName;

  const firstWeekday=new Date(y,m,1).getDay();
  const daysInMonth=new Date(y,m+1,0).getDate();
  const cells=[];
  for(let i=0;i<firstWeekday;i++) cells.push('<button type="button" class="calendar-day empty" tabindex="-1"></button>');

  for(let day=1;day<=daysInMonth;day++){
    const classes=['calendar-day'];
    if(calendarState.mode==='range' && calendarState.start && calendarState.end && day>calendarState.start && day<calendarState.end) classes.push('range');
    if(day===calendarState.start) classes.push('start');
    if(day===calendarState.end) classes.push('end');
    cells.push(`<button type="button" class="${classes.join(' ')}" data-day="${day}">${day}</button>`);
  }

  document.getElementById('calendarDays').innerHTML=cells.join('');
  document.querySelectorAll('#calendarDays [data-day]').forEach(btn=>{
    btn.addEventListener('click',()=>{
      const day=Number(btn.dataset.day);
      if(calendarState.mode==='single'){
        calendarState.start=day;
        calendarState.end=day;
      }else if(!calendarState.start || calendarState.end){
        calendarState.start=day;
        calendarState.end=null;
      }else if(day<calendarState.start){
        calendarState.start=day;
        calendarState.end=null;
      }else{
        calendarState.end=day;
      }
      renderCalendarPicker();
    });
  });

  document.getElementById('calendarSelection').textContent=
    compactRange(y,m,calendarState.start,calendarState.end) || '—';
  document.getElementById('calendarHint').textContent=calendarState.mode==='single'
    ? (!calendarState.start ? 'Select a date.' : 'Date selected. Click Apply.')
    : (!calendarState.start ? 'Select the first day.' :
      !calendarState.end ? 'Now select the last day, or Apply for a single day.' :
      'Range selected. Click Apply.');
}

document.getElementById('calendarPrev').addEventListener('click',()=>{
  calendarState.month--;
  if(calendarState.month<0){calendarState.month=11;calendarState.year--;}
  calendarState.start=null;calendarState.end=null;
  renderCalendarPicker();
});
document.getElementById('calendarNext').addEventListener('click',()=>{
  calendarState.month++;
  if(calendarState.month>11){calendarState.month=0;calendarState.year++;}
  calendarState.start=null;calendarState.end=null;
  renderCalendarPicker();
});
document.getElementById('calendarCancel').addEventListener('click',closeCalendarPicker);
document.getElementById('calendarClear').addEventListener('click',()=>{
  if(calendarState.mode==='single' && calendarState.fieldId){
    document.getElementById(calendarState.fieldId).value='';
  }else if(calendarState.rowIndex!==null){
    itinerary[calendarState.rowIndex].dateRange='';
    renderItinerary();
  }
  closeCalendarPicker();
});
document.getElementById('calendarApply').addEventListener('click',()=>{
  if(!calendarState.start) return;
  if(calendarState.mode==='single' && calendarState.fieldId){
    const selected=[
      calendarState.year,
      String(calendarState.month+1).padStart(2,'0'),
      String(calendarState.start).padStart(2,'0')
    ].join('-');
    document.getElementById(calendarState.fieldId).value=selected;
  }else if(calendarState.rowIndex!==null){
    const selected=compactRange(
      calendarState.year,
      calendarState.month,
      calendarState.start,
      calendarState.end||calendarState.start
    );
    itinerary[calendarState.rowIndex].dateRange=selected;
    renderItinerary();
  }
  closeCalendarPicker();
});
document.getElementById('calendarModal').addEventListener('click',e=>{
  if(e.target.id==='calendarModal') closeCalendarPicker();
});
