function renderItinerary(){
  document.getElementById('itinRows').innerHTML=itinerary.map((r,i)=>`<tr class="border-t">
    <td class="p-1">
      <div class="flex items-center gap-1">
        <input readonly class="form-input !p-1 itin date-range-input calendar-date-input" data-i="${i}" data-k="dateRange"
          placeholder="Select date" value="${esc(r.dateRange||'')}">
        <button type="button" class="open-calendar" data-i="${i}" title="Open calendar" aria-label="Open itinerary date calendar"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="5" width="18" height="16" rx="2"></rect><path d="M16 3v4M8 3v4M3 10h18"></path></svg></button>
      </div>
    </td>
    <td class="p-1"><input class="form-input !p-1 itin" data-i="${i}" data-k="from" value="${esc(r.from)}"></td>
    <td class="p-1"><input class="form-input !p-1 itin" data-i="${i}" data-k="to" value="${esc(r.to)}"></td>
    <td class="p-1"><div class="itinerary-time-control"><input type="time" class="form-input !p-1 itin" data-i="${i}" data-k="departure" value="${esc(r.departure)}"><button type="button" class="clear-itinerary-time${r.departure?' has-time':''}" data-i="${i}" data-k="departure" title="Clear departure time" aria-label="Clear departure time for itinerary row ${i+1}"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m6 6 12 12M18 6 6 18"></path></svg></button></div></td>
    <td class="p-1"><div class="itinerary-time-control"><input type="time" class="form-input !p-1 itin" data-i="${i}" data-k="arrival" value="${esc(r.arrival)}"><button type="button" class="clear-itinerary-time${r.arrival?' has-time':''}" data-i="${i}" data-k="arrival" title="Clear arrival time" aria-label="Clear arrival time for itinerary row ${i+1}"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m6 6 12 12M18 6 6 18"></path></svg></button></div></td>
    <td class="p-1"><input class="form-input !p-1 itin" data-i="${i}" data-k="means" value="${esc(r.means)}"></td>
    <td class="p-1"><input type="number" class="form-input !p-1 itin" data-i="${i}" data-k="transport" value="${Number(r.transport||0)}"></td>
    <td class="p-1"><input type="number" class="form-input !p-1 itin" data-i="${i}" data-k="perDiem" value="${Number(r.perDiem||0)}"></td>
    <td class="p-1"><input type="number" class="form-input !p-1 itin" data-i="${i}" data-k="others" value="${Number(r.others||0)}"></td>
    <td class="p-1"><button type="button" class="itinerary-remove" onclick="removeItin(${i})" title="Remove row" aria-label="Remove itinerary row ${i+1}"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 6h18M8 6V4h8v2M19 6l-1 15H6L5 6M10 11v6M14 11v6"></path></svg></button></td></tr>`).join('');
  document.querySelectorAll('.itin').forEach(el=>el.oninput=e=>{
    const k=e.target.dataset.k,i=+e.target.dataset.i;
    if(k==='dateRange') return;
    itinerary[i][k]=['transport','perDiem','others'].includes(k)?Number(e.target.value||0):e.target.value;
    if(k==='departure'||k==='arrival')e.target.nextElementSibling?.classList.toggle('has-time',Boolean(e.target.value));
    updateTotal();
  });
  document.querySelectorAll('.clear-itinerary-time').forEach(btn=>{
    btn.addEventListener('click',()=>{
      const i=+btn.dataset.i,k=btn.dataset.k;
      itinerary[i][k]='';
      const input=btn.previousElementSibling;
      input.value='';
      btn.classList.remove('has-time');
      input.focus();
    });
  });
  document.querySelectorAll('.date-range-input').forEach(el=>{
    el.addEventListener('click',()=>openCalendarPicker(+el.dataset.i));
  });
  document.querySelectorAll('.open-calendar').forEach(btn=>{
    btn.addEventListener('click',()=>openCalendarPicker(+btn.dataset.i));
  });
  updateTotal();
}
function removeItin(i){itinerary.splice(i,1);renderItinerary()}
document.getElementById('addItinerary').onclick=()=>{itinerary.push({dateRange:'',from:'',to:'',departure:'',arrival:'',means:'',transport:0,perDiem:0,others:0});renderItinerary()}
function total(){return itinerary.reduce((s,r)=>s+Number(r.transport||0)+Number(r.perDiem||0)+Number(r.others||0),0)}
function updateTotal(){document.getElementById('totalAmount').textContent=money(total())}
function collect(){
  const bad=itinerary.findIndex(r=>!validDateRange(r.dateRange));
  if(bad>=0){
    alert(`Itinerary row ${bad+1}: enter the Date like 08/3-6/2026, or 08/3/2026 for a single day.`);
    return null;
  }
  itinerary.forEach(r=>r.dateRange=normalizeDateRange(r.dateRange));
  const id=editingId||('TX-'+Date.now());
  const savedTransaction=getTxs().find(item=>item.id===id);
  const previousTransaction=savedTransaction||(activeTx?.id===id?activeTx:{});
  const templateCompletion=normalizedTemplateCompletion(previousTransaction);
  const t={id,templateCompletion,status:statusFromTemplateCompletion(templateCompletion),itinerary:JSON.parse(JSON.stringify(itinerary)),totalAmount:total()};
  fieldIds.forEach(k=>t[k]=document.getElementById(k).value);return t;
}
async function persistTransaction(t){
  try{
    showApiStatus(editingId?'Saving transaction changes…':'Saving transaction…','info');
    const saved=await apiRequest('/transactions',{method:'POST',body:t});
    const i=transactions.findIndex(x=>x.id===saved.id);
    if(i>=0)transactions[i]=saved;else transactions.unshift(saved);
    activeTx=saved;editingId=saved.id;activeTpl='or';renderPreview();showView('preview');
    showApiStatus('Transaction saved to Google Sheets.','success',2600);
  }catch(error){showApiStatus(error.message,'error')}
}
document.getElementById('txForm').onsubmit=e=>{
  e.preventDefault();const t=collect();if(!t)return;
  openConfirmation({
    title:editingId?'Save transaction changes?':'Save this transaction?',
    message:editingId?'The existing saved transaction will be updated with the information shown below.':'Please review the transaction summary before saving it.',
    confirmText:editingId?'Save Changes':'Save Transaction',
    tone:'save',
    details:[['Transaction Type',t.type||'—'],['OR No.',t.orNo||'—'],['Payee',t.payee||'—'],['Amount',`₱${money(t.totalAmount)}`]],
    onConfirm:()=>persistTransaction(t)
  });
};
document.getElementById('previewWithoutSave').onclick=()=>{const t=collect();if(!t)return;activeTx=t;activeTpl='or';renderPreview();showView('preview')}
document.getElementById('editCurrent').onclick=()=>{if(activeTx){editingId=activeTx.id;loadTransactionFields(activeTx);applyTransactionType();itinerary=normalizeItineraryRows(JSON.parse(JSON.stringify(activeTx.itinerary||[])));renderItinerary();showView('form')}}
document.getElementById('printBtn').onclick=()=>{
  if(!activeTx)return;
  renderPreview();
  window.print();
};
window.addEventListener('beforeprint',()=>{if(activeTx)renderPreview()});

