function renderPreview(){
  if(!activeTx)return;
  activeTx.templateCompletion=normalizedTemplateCompletion(activeTx);
  activeTx.status=statusFromTemplateCompletion(activeTx.templateCompletion);
  const s=getSettings();
  const map={or:renderOR,dv:renderDV,to:renderTO,itinerary:renderItin};
  const labels={or:'Obligation Request',dv:'Disbursement Voucher',to:'Travel Order',itinerary:'Itinerary of Travel'};
  document.getElementById('printArea').innerHTML=map[activeTpl](activeTx,s);
  applyTemplateLogoVisibility();
  document.getElementById('previewTemplateTitle').textContent=labels[activeTpl];
  document.getElementById('previewPayee').textContent=activeTx.payee||'Unnamed Payee';
  document.getElementById('previewMeta').textContent=[activeTx.type,travelDateRange(activeTx),activeTx.destination].filter(Boolean).join(' • ');
  const statusBadge=document.getElementById('previewStatusBadge');
  statusBadge.textContent=activeTx.status;
  statusBadge.className=`preview-status-badge ${activeTx.status.toLowerCase()}`;
  const autoStatus=document.getElementById('previewAutoStatus');
  autoStatus.textContent=activeTx.status;
  autoStatus.className=`preview-auto-status-badge ${activeTx.status.toLowerCase()}`;
  const completedCount=TEMPLATE_KEYS.filter(key=>activeTx.templateCompletion[key]==='complete').length;
  document.getElementById('previewCompletionCount').textContent=`${completedCount} of ${TEMPLATE_KEYS.length} complete`;
  const isSaved=getTxs().some(transaction=>transaction.id===activeTx.id);
  document.getElementById('previewStatusNote').textContent=isSaved?'Template marks and status are saved automatically.':'Save the transaction to keep these template marks permanently.';
  document.querySelectorAll('.template-mark-btn').forEach(button=>{
    const selected=activeTx.templateCompletion[button.dataset.tpl]===button.dataset.mark;
    button.classList.toggle('active',selected);
    button.setAttribute('aria-pressed',String(selected));
  });
  document.querySelectorAll('.tplBtn').forEach(b=>{
    const active=b.dataset.tpl===activeTpl;
    b.classList.toggle('active',active);
    b.closest('.preview-template-item')?.classList.toggle('active',active);
    b.setAttribute('aria-selected',String(active));
  });
  const currentTemplateIndex=TEMPLATE_KEYS.indexOf(activeTpl);
  const nextTemplateButton=document.getElementById('nextTemplateBtn');
  const nextTemplate=TEMPLATE_KEYS[currentTemplateIndex+1];
  nextTemplateButton.disabled=!nextTemplate;
  nextTemplateButton.title=nextTemplate?`Next: ${labels[nextTemplate]}`:'This is the last template';
  nextTemplateButton.setAttribute('aria-label',nextTemplate?`Proceed to ${labels[nextTemplate]}`:'This is the last template');
}

document.querySelectorAll('.tplBtn').forEach(b=>b.onclick=()=>{
  activeTpl=b.dataset.tpl;
  renderPreview();
  saveViewState('preview');
});

document.getElementById('nextTemplateBtn').addEventListener('click',()=>{
  const currentTemplateIndex=TEMPLATE_KEYS.indexOf(activeTpl);
  if(currentTemplateIndex<0||currentTemplateIndex>=TEMPLATE_KEYS.length-1)return;
  activeTpl=TEMPLATE_KEYS[currentTemplateIndex+1];
  renderPreview();
  saveViewState('preview');
});

document.getElementById('templateLogosToggle').addEventListener('click',()=>{
  const enabled=!templateLogosEnabled();
  try{localStorage.setItem(LOGOS_KEY,String(enabled))}catch{}
  applyTemplateLogoVisibility();
});

async function setTemplateCompletion(template,mark){
  if(!activeTx||!TEMPLATE_KEYS.includes(template)||!['complete','incomplete'].includes(mark))return;
  const previousActive=activeTx;
  const templateCompletion={...normalizedTemplateCompletion(activeTx),[template]:mark};
  const status=statusFromTemplateCompletion(templateCompletion);
  activeTx={...activeTx,templateCompletion,status};
  const transactions=getTxs();
  const index=transactions.findIndex(transaction=>transaction.id===activeTx.id);
  if(index>=0){
    transactions[index]={...transactions[index],...activeTx,templateCompletion,status};
    activeTx=transactions[index];
    renderPreview();
    try{
      const saved=await apiRequest('/transactions',{method:'POST',body:activeTx});
      transactions[index]=saved;activeTx=saved;
      showApiStatus('Template status saved.','success',1400);
    }catch(error){
      transactions[index]=previousActive;activeTx=previousActive;
      showApiStatus(error.message,'error');
    }
  }
  renderPreview();
  saveViewState('preview');
}

document.querySelectorAll('.template-mark-btn').forEach(button=>{
  button.addEventListener('click',()=>setTemplateCompletion(button.dataset.tpl,button.dataset.mark));
});

async function restoreViewState(){
  const state=getViewState();
  if(!state||!APP_VIEWS.includes(state.view)){
    showView('dashboard');
    return;
  }

  if(state.view==='preview'){
    activeTx=state.activeTx||null;
    activeTpl=['or','dv','to','itinerary'].includes(state.activeTpl)?state.activeTpl:'or';
    if(!activeTx){
      showView('dashboard');
      return;
    }
    if(transactions.some(transaction=>transaction.id===activeTx.id)){
      activeTx=await fetchTransaction(activeTx.id);
    }
    renderPreview();
  }

  if(state.view==='form'&&state.editingId){
    const transaction=getTxs().find(item=>item.id===state.editingId);
    if(transaction){
      editingId=transaction.id;
      loadTransactionFields(transaction);
      applyTransactionType();
      itinerary=normalizeItineraryRows(JSON.parse(JSON.stringify(transaction.itinerary||[])));
      renderItinerary();
    }
  }

  showView(state.view);
}

function loadSettings(){
  const s=getSettings();
  mayorName.value=s.mayor.name;mayorPos.value=s.mayor.pos;accountantName.value=s.accountant.name;accountantPos.value=s.accountant.pos;
  treasurerName.value=s.treasurer.name;treasurerPos.value=s.treasurer.pos;budgetName.value=s.budget.name;budgetPos.value=s.budget.pos;
}
document.getElementById('settingsForm').onsubmit=e=>{
  e.preventDefault();saveRemoteSettings({
    mayor:{name:mayorName.value,pos:mayorPos.value},accountant:{name:accountantName.value,pos:accountantPos.value},
    treasurer:{name:treasurerName.value,pos:treasurerPos.value},budget:{name:budgetName.value,pos:budgetPos.value}
  });
};
async function saveRemoteSettings(settings){
  try{
    showApiStatus('Saving signatories to Google Sheets…','info');
    systemSettings=await apiRequest('/settings',{method:'PUT',body:settings});
    loadSettings();
    const status=document.getElementById('settingsSaveStatus');
    status.classList.add('show');
    clearTimeout(settingsSaveTimer);
    settingsSaveTimer=setTimeout(()=>status.classList.remove('show'),2400);
    showApiStatus('Settings saved to Google Sheets.','success',2200);
  }catch(error){showApiStatus(error.message,'error')}
}

async function initializeApplication(){
  renderItinerary();applyTemplateLogoVisibility();
  try{
    await loadRemoteState();
    loadSettings();
    await restoreViewState();
  }catch(error){
    remoteReady=false;
    loadSettings();
    renderDashboard();
    showView('dashboard');
    showApiStatus(`${error.message} Transactions cannot be saved until the API is available.`,'error');
  }
}
initializeApplication();
